steps.script:
var PV = load("res://scripts/PlanValidator.gd")
var PM = load("res://scripts/PlanManager.gd")
var fixture = PV.load_plan_file("res://tests/fixtures/ai_plans/fixture_recon_stomps_rich.json")
if fixture.is_empty():
	return "fixture unreadable"
PM.ensure_user_plans_dir()
var path = "user://ai_plans/%s.json" % PM.slugify(str(fixture.get("name", "")))
var f = FileAccess.open(path, FileAccess.WRITE)
f.store_string(JSON.stringify(fixture, "\t"))
f.close()
return "%s|%s|%s" % [path, str(fixture.keys.army_file), str(fixture.keys.deployment_zone_id)]

var m = tree.current_scene
m.p1_disposition_dropdown.selected = 0
m.p2_disposition_dropdown.selected = 1
m._on_disposition_changed(1)
var variant = -1
for i in range(m.terrain_options.size()):
	if str(m.terrain_options[i].id) == "take_and_hold_vs_purge_the_foe_3":
		variant = i
if variant < 0:
	return "variant missing"
m.terrain_dropdown.selected = variant
m._on_terrain_layout_selected(variant)
return m._selected_deployment_id()

var m = tree.current_scene
var idx = -1
for i in range(m.player2_plan_dropdown.item_count):
	if m.player2_plan_dropdown.get_item_text(i).begins_with("Fixture"):
		idx = i
if idx < 0:
	var seen = []
	for i in range(m.player2_plan_dropdown.item_count):
		seen.append(m.player2_plan_dropdown.get_item_text(i))
	return "NOT OFFERED: " + str(seen)
m.player2_plan_dropdown.selected = idx
# "None" for player 1, so the two seats are a controlled comparison.
m.player1_plan_dropdown.selected = 1
return "%s || p1=%s p2=%s" % [m.player2_plan_dropdown.get_item_text(idx),
	m._selected_plan_value(1), m._selected_plan_value(2)]

var n = 0
for uid in GameState.state.units.keys():
	if int(GameState.state.units[uid].get("status", 0)) == 0:
		n += 1
return n

var per_seat = {1: 0, 2: 0}
for batch in AIPlayer._all_decision_records:
	var seat = int(batch.get("player", 0))
	for rec in batch.get("records", []):
		if str(rec.get("decision_type", "")) != "deployment":
			continue
		if str(rec.get("context", {}).get("source", "")).begins_with("plan:"):
			per_seat[seat] = int(per_seat.get(seat, 0)) + 1
print("SCENARIO pm7a plan deployment records: seat1=%d seat2=%d" % [per_seat.get(1, 0), per_seat.get(2, 0)])
return "%d,%d" % [int(per_seat.get(1, 0)), int(per_seat.get(2, 0))]

var per_seat = {1: 0, 2: 0}
for batch in AIPlayer._all_decision_records:
	var seat = int(batch.get("player", 0))
	for rec in batch.get("records", []):
		if str(rec.get("decision_type", "")) != "deployment":
			continue
		if str(rec.get("context", {}).get("source", "")).begins_with("plan:"):
			per_seat[seat] = int(per_seat.get(seat, 0)) + 1
print("SCENARIO pm7a plan deployment records: seat1=%d seat2=%d" % [per_seat.get(1, 0), per_seat.get(2, 0)])
return int(per_seat.get(2, 0))

var per_seat = {1: 0, 2: 0}
for batch in AIPlayer._all_decision_records:
	var seat = int(batch.get("player", 0))
	for rec in batch.get("records", []):
		if str(rec.get("decision_type", "")) != "deployment":
			continue
		if str(rec.get("context", {}).get("source", "")).begins_with("plan:"):
			per_seat[seat] = int(per_seat.get(seat, 0)) + 1
print("SCENARIO pm7a plan deployment records: seat1=%d seat2=%d" % [per_seat.get(1, 0), per_seat.get(2, 0)])
return int(per_seat.get(1, 0))

var p = tree.root.find_child("AITurnSummaryPanel", true, false)
if p == null:
	return "panel missing"
return p._plan_line(2)
